//! Round-trip tests against the committed fixture snapshot (generated by the
//! Python pipeline: `python -m pipeline.cli --out ./sample --offline --date 2026-11-14`).

use rebellion_core::{aggregate, days_to_iso, decode};

static SNAPSHOT: &[u8] = include_bytes!("fixtures/snapshot.bin");

#[test]
fn decode_fixture_has_strikes() {
    let snap = decode(SNAPSHOT).expect("fixture should decode");
    assert!(!snap.strikes.is_empty());
    // The fixture was generated with --date 2026-11-14.
    assert_eq!(days_to_iso(snap.date_days), "2026-11-14");
}

#[test]
fn every_record_is_well_formed() {
    let snap = decode(SNAPSHOT).unwrap();
    for s in &snap.strikes {
        assert!((-90.0..=90.0).contains(&s.lat));
        assert!((-180.0..=180.0).contains(&s.lon));
        assert!((-90.0..=90.0).contains(&s.origin_lat));
        assert!(s.severity <= 3);
        assert!(s.witness <= 6);
        assert_eq!(s.country_str().len(), 2);
    }
}

#[test]
fn ids_are_unique() {
    let snap = decode(SNAPSHOT).unwrap();
    let mut ids: Vec<u32> = snap.strikes.iter().map(|s| s.id).collect();
    ids.sort_unstable();
    ids.dedup();
    assert_eq!(ids.len(), snap.strikes.len());
}

#[test]
fn aggregate_builds_points_and_arcs() {
    let snap = decode(SNAPSHOT).unwrap();
    let batch = aggregate(&snap, None);

    assert_eq!(batch.date, "2026-11-14");
    assert_eq!(batch.total as usize, snap.strikes.len());
    // One point per strike (strikes are not merged), each carrying its id.
    assert_eq!(batch.points.len(), snap.strikes.len());
    assert_eq!(batch.arcs.len(), snap.strikes.len()); // below the LOD cap
    assert_eq!(batch.counts.iter().sum::<u32>(), batch.total);
}

#[test]
fn arc_cap_is_respected() {
    let snap = decode(SNAPSHOT).unwrap();
    let batch = aggregate(&snap, Some(3));
    assert!(batch.arcs.len() <= 3);
    // Highest severity arcs are kept first.
    if batch.arcs.len() >= 2 {
        assert!(batch.arcs[0].severity >= batch.arcs[1].severity);
    }
}

#[test]
fn rejects_bad_magic() {
    let mut bad = SNAPSHOT.to_vec();
    bad[0] = b'X';
    assert!(decode(&bad).is_err());
}

#[test]
fn rejects_wrong_version() {
    let mut bad = SNAPSHOT.to_vec();
    bad[4] = 1; // legacy version
    assert!(decode(&bad).is_err());
}

#[test]
fn days_to_iso_known_values() {
    assert_eq!(days_to_iso(0), "1970-01-01");
    assert_eq!(days_to_iso(20771), "2026-11-14");
}
